// The status pip: one shape per state, always paired with a word, never colour alone.
// Same device for run status, the connection badge, the tally and the empty state.
const GLYPH = {
  ok:   '<circle class="f" cx="8" cy="8" r="7"/><path d="M4.8 8.3l2.2 2.2 4.2-4.4"/>',
  fail: '<circle class="f" cx="8" cy="8" r="7"/><path d="M5.5 5.5l5 5m0-5l-5 5"/>',
  run:  '<circle cx="8" cy="8" r="6" stroke-dasharray="3 2.2"/>',
  idle: '<circle cx="8" cy="8" r="6"/>',
};

export function pip(kind, label) {
  return `<span class="pip pip-${kind}"><svg viewBox="0 0 16 16" aria-hidden="true">${GLYPH[kind]}</svg>${label}</span>`;
}

// Connection state comes from the caller. Nothing here claims "Connected" on its own.
export function renderBadge(live) {
  return `<span class="badge">${live ? pip('ok', 'Connected') : pip('idle', 'Demo data, not connected')}</span>`;
}

