    <td class="act"><button type="button" class="btn retry" data-run="${r.id}" ${off}>Retry<span class="vh"> ${r.id}</span></button></td>
  </tr>`;
}

function table(runs) {
  if (!runs.length) {
    return `<div class="empty">${pip('idle', 'No runs yet')}<p>Runs show up here as soon as a deploy starts.</p></div>`;
  }
  return `<div class="scroll" role="region" aria-labelledby="runs-h" tabindex="0">
    <table>
      <thead><tr>
        <th scope="col">Run</th><th scope="col">Service</th><th scope="col">Status</th>
        <th scope="col" class="num">Started</th><th scope="col" class="num">Duration</th>
        <th scope="col" class="act"><span class="vh">Actions</span></th>
      </tr></thead>
      <tbody>${runs.map(row).join('')}</tbody>
    </table>
  </div>`;
}

function tally(runs) {
  const failed = runs.filter((r) => r.status === 'failed').length;
  const passed = runs.filter((r) => r.status === 'passed').length;
  return [failed && pip('fail', `${failed} failed`), passed && pip('ok', `${passed} passed`)]
    .filter(Boolean).join('');
}

export function render(runs = RUNS) {
  document.querySelector('#app').innerHTML = `
    <header class="bar">
      <div class="brand"><span class="mark">pulse</span>${renderBadge(LIVE)}</div>
      <button type="button" id="new-run" class="btn primary" ${off}>New run</button>
    </header>
    <main>
      <div class="head">
        <h1 id="runs-h">Deploy runs</h1>
        <p class="tally">${tally(runs)}</p>
      </div>
      ${LIVE ? '' : '<p id="off-note" class="note">Retry and New run are off while pulse shows demo data. They switch on once it is connected to the deploy API.</p>'}
      ${table(runs)}
      <p id="feedback" class="feedback" role="status"></p>
    </main>`;

  const say = (msg) => { document.querySelector('#feedback').textContent = msg; };

  document.querySelectorAll('.retry').forEach((b) => {
    b.addEventListener('click', () => {
      if (!LIVE) return say(`Nothing was retried. ${b.dataset.run} is demo data.`);
    });
  });
  document.querySelector('#new-run').addEventListener('click', () => {
    if (!LIVE) return say('Nothing was started. New run is off while pulse shows demo data.');
  });
}

render();

