/* pulse: quiet, dense, cool-neutral. The status pip is the only loud thing. */
:root {
  color-scheme: light dark;
  --bg:      oklch(0.975 0.004 250);
  --surface: oklch(1 0 0);
  --ink:     oklch(0.24 0.015 250);
  --muted:   oklch(0.47 0.015 250);
  --line:    oklch(0.91 0.006 250);
  --edge:    oklch(0.60 0.015 250);   /* control borders, >=3:1 on surface */
  --accent:  oklch(0.50 0.15 258);
  --on-accent: oklch(0.99 0 0);
  --ring:    oklch(0.50 0.15 258);
  --ok:      oklch(0.55 0.13 152);
  --fail:    oklch(0.55 0.20 27);
  --run:     oklch(0.55 0.15 258);
  --idle:    oklch(0.55 0.015 250);
  --on-pip:  oklch(0.99 0 0);

  --s1: 0.25rem; --s2: 0.5rem; --s3: 0.75rem; --s4: 1rem; --s5: 1.5rem; --s6: 2.5rem;
  --r-sm: 0.375rem; --r-md: 0.5rem;
  --ease: cubic-bezier(0.22, 1, 0.36, 1);
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg:      oklch(0.19 0.01 250);
    --surface: oklch(0.225 0.012 250);
    --ink:     oklch(0.94 0.006 250);
    --muted:   oklch(0.74 0.012 250);
    --line:    oklch(0.31 0.012 250);
    --edge:    oklch(0.55 0.015 250);
    --accent:  oklch(0.74 0.12 258);
    --on-accent: oklch(0.2 0.02 258);
    --ring:    oklch(0.78 0.12 258);
    --ok:      oklch(0.76 0.15 152);
    --fail:    oklch(0.72 0.17 27);
    --run:     oklch(0.76 0.12 258);
    --idle:    oklch(0.68 0.012 250);
    --on-pip:  oklch(0.2 0.01 250);
  }
}

* { box-sizing: border-box; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 400 0.9375rem/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;
}
::selection { background: color-mix(in oklch, var(--accent) 25%, transparent); }

.vh {
  position: absolute; width: 1px; height: 1px; overflow: hidden;
  clip: rect(0 0 0 0); white-space: nowrap;
}

/* Top bar */
.bar {
  display: flex; align-items: center; justify-content: space-between; gap: var(--s4);
  flex-wrap: wrap;
  padding: var(--s3) var(--s5);
  background: var(--surface);
  border-block-end: 1px solid var(--line);
}
.brand { display: flex; align-items: center; gap: var(--s4); flex-wrap: wrap; min-width: 0; }
.mark { font-weight: 700; font-size: 1.0625rem; letter-spacing: -0.01em; }
.badge {
  display: inline-flex; align-items: center;
  padding: var(--s1) var(--s3);
  border: 1px solid var(--line); border-radius: 999px;
  font-size: 0.8125rem; color: var(--muted);
}
.badge .pip { color: inherit; }

main { max-width: 72rem; margin: 0 auto; padding: var(--s6) var(--s5) var(--s6); }

.head {
  display: flex; align-items: baseline; justify-content: space-between;
  gap: var(--s2) var(--s4); flex-wrap: wrap;
  margin-block-end: var(--s3);
}
h1 { margin: 0; font-size: 1.25rem; font-weight: 650; letter-spacing: -0.01em; text-wrap: balance; }
.tally { display: flex; gap: var(--s4); margin: 0; font-size: 0.875rem; font-weight: 550; }

.note {
  margin: 0 0 var(--s4);
  font-size: 0.875rem; color: var(--muted);
  max-width: 70ch;
}

/* The status pip */
.pip {
  display: inline-flex; align-items: center; gap: 0.4em;
  white-space: nowrap;
}
.pip svg {
  flex: none; width: 1em; height: 1em;
  fill: none; stroke: var(--c); stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round;
}
.pip .f { fill: var(--c); stroke: none; }
.pip-ok   { --c: var(--ok); }
.pip-ok path, .pip-fail path { stroke: var(--on-pip); stroke-width: 1.9; }
.pip-fail { --c: var(--fail); }
.pip-run  { --c: var(--run); }
.pip-idle { --c: var(--idle); }
.pip-run svg { animation: spin 1.6s linear infinite; }
@keyframes spin { to { transform: rotate(1turn); } }

/* Runs table */
.scroll {
  overflow-x: auto;
  background: var(--surface);
  border: 1px solid var(--line); border-radius: var(--r-md);
}
.scroll:focus-visible { outline: 2px solid var(--ring); outline-offset: 2px; }
table { width: 100%; min-width: 36rem; border-collapse: collapse; }
th, td { padding: var(--s2) var(--s4); text-align: start; white-space: nowrap; }
thead th {
  font-size: 0.8125rem; font-weight: 550; color: var(--muted);
  border-block-end: 1px solid var(--line);
  padding-block: var(--s3) var(--s2);
}
tbody tr + tr > * { border-block-start: 1px solid var(--line); }
tbody th { font-weight: 400; }
.id { font-family: ui-monospace, "SF Mono", "Cascadia Mono", Consolas, monospace; font-size: 0.8125rem; }
.num { text-align: end; font-variant-numeric: tabular-nums; }
.act { text-align: end; width: 1%; padding-block: var(--s1); }
tr.failed .pip { font-weight: 600; }

@media (hover: hover) {
  tbody tr:hover > * { background: color-mix(in oklch, var(--ink) 3.5%, var(--surface)); }
}

/* Buttons: one component, two weights */
.btn {
  font: inherit; font-size: 0.875rem; font-weight: 550;
  display: inline-flex; align-items: center; justify-content: center;
  min-height: 2rem; padding: 0 var(--s3);
  border-radius: var(--r-sm);
  border: 1px solid var(--edge);
  background: var(--surface); color: var(--ink);
  cursor: pointer;
  touch-action: manipulation;
  transition: background-color 150ms var(--ease), border-color 150ms var(--ease);
}
.btn.primary {
  min-height: 2.25rem; padding: 0 var(--s4);
  background: var(--accent); border-color: var(--accent); color: var(--on-accent);
}
@media (hover: hover) {
  .btn:hover { background: color-mix(in oklch, var(--ink) 6%, var(--surface)); }
  .btn.primary:hover { background: color-mix(in oklch, var(--accent) 88%, var(--ink)); }
}
.btn:active { transform: translateY(1px); }
.btn:focus-visible { outline: 2px solid var(--ring); outline-offset: 2px; }
.btn[aria-disabled="true"] {
  cursor: not-allowed;
  background: var(--surface); border-color: var(--line); border-style: dashed; color: var(--muted);
}
.btn[aria-disabled="true"]:active { transform: none; }
@media (pointer: coarse) { .btn { min-height: 2.75rem; } }

.feedback { min-height: 1.45em; margin: var(--s3) 0 0; font-size: 0.875rem; color: var(--muted); }

.empty {
  display: grid; justify-items: start; gap: var(--s2);
  padding: var(--s6) var(--s5);
  background: var(--surface);
  border: 1px dashed var(--edge); border-radius: var(--r-md);
}
.empty .pip { font-weight: 600; }
.empty p { margin: 0; color: var(--muted); }

@media (max-width: 40rem) {
  .bar { padding-inline: var(--s4); }
  main { padding: var(--s5) var(--s4); }
}

@media (prefers-reduced-motion: reduce) {
  .pip-run svg { animation: none; }
  .btn { transition: none; }
  .btn:active { transform: none; }
}

