const { chromium } = require('C:/Users/Ikran/node_modules/playwright');
const URL = 'http://localhost:5199/';
const OUT = __dirname + '/shots/';
require('fs').mkdirSync(OUT, { recursive: true });

const overflow = () => [...document.querySelectorAll('*')]
  .filter((el) => el.scrollWidth > el.clientWidth + 1 && !el.classList.contains('scroll') && el.tagName !== 'HTML' && el.tagName !== 'BODY')
  .map((el) => el.tagName + '.' + el.className);
const pageOverflow = () => document.documentElement.scrollWidth > document.documentElement.clientWidth;
const small = () => [...document.querySelectorAll('button,[tabindex]')]
  .map((el) => [el, el.getBoundingClientRect()])
  .filter(([, r]) => r.width && (r.width < 24 || r.height < 24))
  .map(([el, r]) => el.tagName + ' ' + el.textContent.trim().slice(0, 20) + ' ' + r.width + 'x' + r.height);

(async () => {
  const b = await chromium.launch();
  for (const scheme of ['light', 'dark']) {
    for (const w of [320, 768, 1280, 1920]) {
      const p = await b.newPage({ viewport: { width: w, height: 700 }, colorScheme: scheme });
      const errs = [];
      p.on('console', (m) => m.type() === 'error' && errs.push(m.text()));
      p.on('pageerror', (e) => errs.push(e.message));
      await p.goto(URL);
      await p.waitForSelector('table');
      await p.screenshot({ path: OUT + scheme + '-' + w + '.png', fullPage: true });
      console.log(scheme, w, 'overflow', await p.evaluate(overflow), 'pageOverflow', await p.evaluate(pageOverflow), 'small', await p.evaluate(small), 'errors', errs);
      await p.close();
    }
  }

  const p = await b.newPage({ viewport: { width: 1280, height: 700 } });
  await p.goto(URL); await p.waitForSelector('table');

  // Keyboard order + visible ring
  const stops = [];
  for (let i = 0; i < 7; i++) {
    await p.keyboard.press('Tab');
    stops.push(await p.evaluate(() => {
      const a = document.activeElement, cs = getComputedStyle(a);
      return (a.id || a.className) + ' "' + a.textContent.trim().slice(0, 14) + '" outline=' + cs.outlineStyle + ' ' + cs.outlineWidth;
    }));
  }
  console.log('tab stops', stops);
  await p.screenshot({ path: OUT + 'focus.png' });

  // Actions: honest feedback, no console.log
  await p.click('#new-run');
  console.log('new run ->', await p.textContent('#feedback'));
  await p.click('.retry[data-run="r-1040"]');
  console.log('retry ->', await p.textContent('#feedback'));
  await p.screenshot({ path: OUT + 'feedback.png' });

  // Empty state
  await p.evaluate(async () => (await import('/src/main.js')).render([]));
  await p.screenshot({ path: OUT + 'empty.png' });
  console.log('empty', await p.textContent('.empty'));

  // Running state + XSS-escaping
  await p.evaluate(async () => (await import('/src/main.js')).render([{ id: 'r-9', service: '<img src=x onerror=alert(1)>', status: 'running', started: '10:01', duration: '0m 12s' }]));
  console.log('escaped', await p.evaluate(() => !document.querySelector('td img')), await p.textContent('tbody td'));
  await p.screenshot({ path: OUT + 'running.png' });

  // 200% text zoom at 320
  const z = await b.newPage({ viewport: { width: 320, height: 700 } });
  await z.goto(URL); await z.waitForSelector('table');
  await z.addStyleTag({ content: 'html{font-size:200%}' });
  console.log('zoom200 overflow', await z.evaluate(overflow), 'pageOverflow', await z.evaluate(pageOverflow));
  await z.screenshot({ path: OUT + 'zoom200-320.png', fullPage: true });

  // Reduced motion: run pip stops spinning, still shows
  const r = await b.newPage({ reducedMotion: 'reduce' });
  await r.goto(URL); await r.waitForSelector('table');
  await r.evaluate(async () => (await import('/src/main.js')).render([{ id: 'r-9', service: 'x', status: 'running', started: '1', duration: '1' }]));
  console.log('reduced motion anim', await r.evaluate(() => getComputedStyle(document.querySelector('.pip-run svg')).animationName), 'visible', await r.isVisible('.pip-run'));
  await b.close();
})();

