/* pulse: quiet, dense, cool-neutral. The status pip is the only loud thing. */
:root {
  color-scheme: light dark;
  --bg:      oklch(0.975 0.004 250);
  --surface: oklch(1 0 0);
  --ink:     oklch(0.24 0.015 250);
  --muted:   oklch(0.47 0.015 250);
  --line:    oklch(0.91 0.006 250);
  --edge:    oklch(0.60 0.015 250);   /* control borders, >=3:1 on surface */
  --accent:  oklch(0.50 0.15 258);
  --on-accent: oklch(0.99 0 0);
  --ring:    oklch(0.50 0.15 258);
  --ok:      oklch(0.55 0.13 152);
  --fail:    oklch(0.55 0.20 27);
  --run:     oklch(0.55 0.15 258);
  --idle:    oklch(0.55 0.015 250);
  --on-pip:  oklch(0.99 0 0);

  --s1: 0.25rem; --s2: 0.5rem; --s3: 0.75rem; --s4: 1rem; --s5: 1.5rem; --s6: 2.5rem;
  --r-sm: 0.375rem; --r-md: 0.5rem;
  --ease: cubic-bezier(0.22, 1, 0.36, 1);
}

