tbody th { font-weight: 400; }
.id { font-family: ui-monospace, "SF Mono", "Cascadia Mono", Consolas, monospace; font-size: 0.8125rem; }
.num { text-align: end; font-variant-numeric: tabular-nums; }
.act { text-align: end; width: 1%; padding-block: var(--s1); }
tr.failed .pip { font-weight: 600; }

@media (hover: hover) {
  tbody tr:hover > * { background: color-mix(in oklch, var(--ink) 3.5%, var(--surface)); }
}

/* Buttons: one component, two weights */
.btn {
  font: inherit; font-size: 0.875rem; font-weight: 550;
  display: inline-flex; align-items: center; justify-content: center;
  min-height: 2rem; padding: 0 var(--s3);
  border-radius: var(--r-sm);
  border: 1px solid var(--edge);
  background: var(--surface); color: var(--ink);
  cursor: pointer;
  touch-action: manipulation;
  transition: background-color 150ms var(--ease), border-color 150ms var(--ease);
}
.btn.primary {
  min-height: 2.25rem; padding: 0 var(--s4);
  background: var(--accent); border-color: var(--accent); color: var(--on-accent);
}
@media (hover: hover) {
  .btn:hover { background: color-mix(in oklch, var(--ink) 6%, var(--surface)); }
  .btn.primary:hover { background: color-mix(in oklch, var(--accent) 88%, var(--ink)); }
}
.btn:active { transform: translateY(1px); }
.btn:focus-visible { outline: 2px solid var(--ring); outline-offset: 2px; }
.btn[aria-disabled="true"] {
  cursor: not-allowed;
  background: var(--surface); border-color: var(--line); border-style: dashed; color: var(--muted);
}
.btn[aria-disabled="true"]:active { transform: none; }
@media (pointer: coarse) { .btn { min-height: 2.75rem; } }

.feedback { min-height: 1.45em; margin: var(--s3) 0 0; font-size: 0.875rem; color: var(--muted); }

.empty {
  display: grid; justify-items: start; gap: var(--s2);
  padding: var(--s6) var(--s5);
  background: var(--surface);
  border: 1px dashed var(--edge); border-radius: var(--r-md);
}
.empty .pip { font-weight: 600; }
.empty p { margin: 0; color: var(--muted); }

@media (max-width: 40rem) {
  .bar { padding-inline: var(--s4); }
  main { padding: var(--s5) var(--s4); }
}

@media (prefers-reduced-motion: reduce) {
  .pip-run svg { animation: none; }
  .btn { transition: none; }
  .btn:active { transform: none; }
}
